
import type { StripePaymentClientAction } from './StripePaymentClientAction.js';

/** Client-side action required before continuing a payment. Resume an order through PayOrder with order_payment_attempt_id, or continue a standalone PaymentIntent through its confirm endpoint without a replacement credential. */ export type PendingPaymentAction = { /** Product-level action type. payment_authentication applies to a payment leg; payment_method_authentication applies to saving a future-billing payment method. */ "action_type": "payment_authentication" | "payment_method_authentication" | (string & {}); /** Direct browser authority required to finish this action before continuing through Flint. Unlike collection guidance, this payload includes a client secret. */ "client_action": { "stripe": StripePaymentClientAction; }; /** Stable Flint action ID. Use this to deduplicate a repeated action projection while resuming an attempt. */ "pending_action_id": string; /** The attempt subject that requires browser action. Exactly one of payment_intent or setup_payment_source is present. */ "subject": { /** PaymentIntent that requires buyer authentication. It can be a standalone intent or an order-owned payment leg. */ "payment_intent"?: { "payment_intent_id": string; }; /** Future-billing payment method setup that requires buyer authentication. */ "setup_payment_source"?: { "payment_method_id": string; }; }; };
